async function* nativeRevision(args, cwd, grok = false) {
  const controller = new AbortController();
  const signal = args.signal ?? controller.signal;
  for await (const event of (grok ? grokCodeTurn : claudeCodeTurn)({
    ...args,
    cwd,
    signal,
    maxIterations: 1,
    registry: new ToolRegistry(),
    permissionGate: new PermissionGate({ oneShot: false, autoApprove: /* @__PURE__ */ new Set(), ask: async () => "no" })
  })) {
    if (event.kind === "text_delta") yield { type: "text_delta", text: event.text };
    if (event.kind === "error") yield { type: "error", error: event.message };
  }
}
