function openExternal(url) {
  try {
    const electron = window.require?.("electron");
    const shell = electron?.shell;
    if (shell?.openExternal) {
      void shell.openExternal(url);
      return;
    }
  } catch {
  }
  window.open(url, "_blank");
}
function friendlyAuthError(message) {
  if (message.includes("HTTP 429") || message.includes("rate_limit")) {
    return message + "\n\nThe identity provider is rate-limiting this request. Wait before trying again.";
  }
  if (message.includes("HTTP 400") && message.includes("invalid_grant")) {
    return message + "\n\nThe authorization is expired or no longer valid. Restart this sign-in flow.";
  }
  if (message.includes("Failed to fetch")) {
    return message + "\n\nNetwork error reaching the identity provider. Check your connection; if you're on a corporate VPN, the OAuth endpoint may be blocked.";
  }
  return message;
}
